pdfjsLib.GlobalWorkerOptions.workerSrc="https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.worker.min.js";const dropZone=document.getElementById("drop-zone"),fileInput=document.getElementById("file-input"),loading=document.getElementById("loading"),quizContainer=document.getElementById("quiz-container"),questionsList=document.getElementById("questions-list");async function processFile(e){if(e){dropZone.style.display="none",loading.style.display="block";try{const t=await e.arrayBuffer(),n=await pdfjsLib.getDocument(t).promise;let i="";for(let e=1;e<=n.numPages;e++){const t=await n.getPage(e);i+=(await t.getTextContent()).items.map(e=>e.str).join(" ")+" "}generateQuiz(i)}catch(e){alert("Error processing PDF."),location.reload()}}}function generateQuiz(e){loading.style.display="none",quizContainer.style.display="block";const t=e.match(/[^.!?]+[.!?]+/g)||[],n=[/\b(is|are) defined as\b/i,/\brefers to\b/i,/\bis a type of\b/i,/\b(is|are) the process of\b/i,/\b(is|are) known as\b/i];let i=[];t.forEach(e=>{if(n.some(t=>t.test(e))&&e.split(" ").length>8){let t="",n="";if(e.toLowerCase().includes(" is ")){const i=e.split(/ is /i);t=i[0].trim(),n=i[1].trim()}t&&n&&i.length<5&&i.push({type:"mcq",question:`What is the definition of "${t}"?`,answer:n,distractors:["A byproduct of the inverse process.","A non-essential component in this context.","The opposite of the intended effect."]})}}),0===i.length&&i.push({type:"mcq",question:"Based on the text, what is a primary focus of this document?",answer:"Comprehensive analysis of the subject matter.",distractors:["Casual conversation.","External marketing strategy.","Historical archives only."]}),questionsList.innerHTML=i.map((e,t)=>`\n                <div class="question-card">\n                    <div class="question-text">${t+1}. ${e.question}</div>\n                    <div class="options-list">\n                        ${[e.answer,...e.distractors].sort(()=>Math.random()-.5).map(t=>`\n                            <div class="option-item" onclick="checkAnswer(this, '${t===e.answer}')">${t}</div>\n                        `).join("")}\n                    </div>\n                </div>\n            `).join(""),setTimeout(()=>{triggerAutoDownload(i.map((e,t)=>`Q${t+1}: ${e.question}\nAnswer: ${e.answer}`).join("\n\n"))},1500)}function checkAnswer(e,t){"true"===t?(e.classList.add("correct"),e.innerText+=" ✓"):(e.classList.add("wrong"),e.innerText+=" ✗"),e.parentElement.querySelectorAll(".option-item").forEach(e=>e.style.pointerEvents="none")}function triggerAutoDownload(e){const t=new Blob([e],{type:"text/plain"}),n=URL.createObjectURL(t),i=document.createElement("a");i.href=n,i.download="generated_quiz.txt",i.click()}dropZone.onclick=()=>fileInput.click(),fileInput.onchange=e=>processFile(e.target.files[0]);